(window.__quranSurahs=window.__quranSurahs||{})[70]={"nomPhon":"Al-Ma'aarij","versets":{"1":{"text":"Un demandeur a réclamé un châtiment inéluctable,","arabe":"سَأَلَ سَآئِلٌۢ بِعَذَابٍۢ وَاقِعٍۢ"},"2":{"text":"pour les mécréants, que nul ne pourrait repousser,","arabe":"لِّلْكَٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌۭ"},"3":{"text":"et qui vient d'Allah, le Maître des voies d'ascension.","arabe":"مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ"},"4":{"text":"Les Anges ainsi que l'Esprit montent vers Lui en un jour dont la durée est de cinquante mille ans.","arabe":"تَعْرُجُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍۢ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍۢ"},"5":{"text":"Supporte donc, d'une belle patience.","arabe":"فَٱصْبِرْ صَبْرًۭا جَمِيلًا"},"6":{"text":"Ils le (le châtiment) voient bien loin,","arabe":"إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًۭا"},"7":{"text":"alors que Nous le voyons bien proche,","arabe":"وَنَرَىٰهُ قَرِيبًۭا"},"8":{"text":"le jour où le ciel sera comme du métal en fusion","arabe":"يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ"},"9":{"text":"et les montagnes comme de la laine,","arabe":"وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ"},"10":{"text":"où nul ami dévoué ne s'enquerra d'un ami,","arabe":"وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًۭا"},"11":{"text":"bien qu'ils se voient l'un l'autre. Le criminel aimerait pouvoir se racheter du châtiment de ce jour, en livrant ses enfants,","arabe":"يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ"},"12":{"text":"sa compagne, son frère,","arabe":"وَصَٰحِبَتِهِۦ وَأَخِيهِ"},"13":{"text":"même son clan qui lui donnait asile,","arabe":"وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ"},"14":{"text":"et tout ce qui est sur la terre, tout, qui pourrait le sauver.","arabe":"وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا ثُمَّ يُنجِيهِ"},"15":{"text":"Mais rien [ne le sauvera]. [L'Enfer] est un brasier","arabe":"كَلَّآ ۖ إِنَّهَا لَظَىٰ"},"16":{"text":"arrachant brutalement la peau du crâne.","arabe":"نَزَّاعَةًۭ لِّلشَّوَىٰ"},"17":{"text":"Il appellera celui qui tournait le dos et s'en allait,","arabe":"تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ"},"18":{"text":"amassait et thésaurisait.","arabe":"وَجَمَعَ فَأَوْعَىٰٓ"},"19":{"text":"Oui, l'homme a été créé instable [très inquiet];","arabe":"۞ إِنَّ ٱلْإِنسَٰنَ خُلِقَ هَلُوعًا"},"20":{"text":"quand le malheur le touche, il est abattu;","arabe":"إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًۭا"},"21":{"text":"et quand le bonheur le touche, il est grand refuseur.","arabe":"وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا"},"22":{"text":"Sauf ceux qui pratiquent la Salât","arabe":"إِلَّا ٱلْمُصَلِّينَ"},"23":{"text":"qui sont assidus à leurs Salâts,","arabe":"ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ"},"24":{"text":"et sur les biens desquels il y a un droit bien déterminé [la Zakât]","arabe":"وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّۭ مَّعْلُومٌۭ"},"25":{"text":"pour le mendiant et le déshérité;","arabe":"لِّلسَّآئِلِ وَٱلْمَحْرُومِ"},"26":{"text":"et qui déclarent véridique le Jour de la Rétribution,","arabe":"وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ"},"27":{"text":"et ceux qui craignent le châtiment de leur Seigneur","arabe":"وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ"},"28":{"text":"car vraiment, il n'y a nulle assurance contre le châtiment de leur Seigneur;","arabe":"إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍۢ"},"29":{"text":"et qui se maintiennent dans la chasteté","arabe":"وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ"},"30":{"text":"et n'ont de rapports qu'avec leurs épouses ou les esclaves qu'ils possèdent car dans ce cas, ils ne sont pas blâmables,","arabe":"إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ"},"31":{"text":"mais ceux qui cherchent [leur plaisir] en dehors de cela, sont des transgresseurs;","arabe":"فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ"},"32":{"text":"et qui gardent les dépôts confiés à eux, et respectent leurs engagements scrupuleusement;","arabe":"وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ"},"33":{"text":"et qui témoignent de la stricte vérité,","arabe":"وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمْ قَآئِمُونَ"},"34":{"text":"et qui sont réguliers dans leur Salât.","arabe":"وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ"},"35":{"text":"Ceux-là seront honorés dans des Jardins.","arabe":"أُو۟لَٰٓئِكَ فِى جَنَّٰتٍۢ مُّكْرَمُونَ"},"36":{"text":"Qu'ont donc, ceux qui ont mécru, à courir vers toi, le cou tendu,","arabe":"فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ"},"37":{"text":"de droite et de gauche, [venant] par bandes?","arabe":"عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ"},"38":{"text":"Chacun d'eux convoite-t-il qu'on le laisse entrer au Jardin des délices?","arabe":"أَيَطْمَعُ كُلُّ ٱمْرِئٍۢ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍۢ"},"39":{"text":"Mais non! Nous les avons créés de ce qu'ils savent.","arabe":"كَلَّآ ۖ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ"},"40":{"text":"Eh Non!... Je jure par le Seigneur des Levants et des Couchants que Nous sommes Capable","arabe":"فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَٰرِقِ وَٱلْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ"},"41":{"text":"de les remplacer par de meilleurs qu'eux, et nul ne peut nous en empêcher.","arabe":"عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًۭا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ"},"42":{"text":"Laisse-les donc s'enfoncer (dans leur mécréance) et se divertir jusqu'à ce qu'ils rencontrent leur jour dont on les menaçait,","arabe":"فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ"},"43":{"text":"le jour où ils sortiront des tombes, rapides comme s'ils couraient vers des pierres dressées;","arabe":"يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًۭا كَأَنَّهُمْ إِلَىٰ نُصُبٍۢ يُوفِضُونَ"},"44":{"text":"leurs yeux seront abaissés, l'avilissement les couvrira. C'est cela le jour dont on les menaçait!","arabe":"خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌۭ ۚ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ"}}};